package aac

// SBR's tables. Written for CloudBurrow (#1739) from PacketVideo's OpenCORE
// AAC decoder (Apache License 2.0; Android's frameworks/av at
// android-4.1.1_r1, media/libstagefright/codecs/aacdec), which carries the
// tables of ISO/IEC 14496-3 Annex 4.A:
//
//   - the Huffman tables of Table 4.A.79 to 4.A.88, as the binary trees of
//     sbr_code_book_envlevel.cpp (a pair per node: a positive entry is the
//     next node, any other a leaf whose symbol is the entry plus 64);
//   - the noise table V of Table 4.A.89, as the 16-bit fixed-point pairs
//     (real high, imaginary low, Q15) of sbr_envelope_calc_tbl.cpp's rPxx;
//   - the QMF window c of Table 4.A.90: its even coefficients c[2n+128j]
//     for 1 <= n <= 31 as qmf_filterbank_coeff.cpp's
//     sbrDecoderFilterbankCoefficients_an_filt gives them (nine digits),
//     the rest by the window's symmetry c[n] = c[640-n] and, for the
//     odd ones and c[64k], by 8-point Lagrange interpolation of the
//     prototype |c| (whose sign alternates every 128 coefficients). The
//     interpolation's error, measured by predicting each given
//     coefficient from its neighbours two apart, is below 1.3e-5 (3.7e-5 at
//     c[2]); between neighbours one apart it is smaller still.

func init() {
	for i, v := range sbrNoiseQ15 {
		sbrNoise[i] = [2]float64{float64(int16(v>>16)) / 32768, float64(int16(v)) / 32768}
	}
}

